fun get(key: String): ByteArray? {
    if (memtable.containsKey(key)) return memtable[key]      // null = tombstone
    for (t in tables) {                                    // newest first
        when (val r = t.get(key)) {
            is Lookup.Value -> return r.bytes
            Lookup.Tombstone -> return null                // deleted: stop looking
            Lookup.Missing -> continue
        }
    }
    return null
}

fun compact() {
    val merged = TreeMap<String, ByteArray?>()
    for (t in tables.asReversed()) for ((k, v) in t.entries()) merged[k] = v   // newer overwrite older
    val live = TreeMap<String, ByteArray?>()
    for ((k, v) in merged) if (v != null) live[k] = v
    val out = SSTable.write(dir.resolve(fileName(nextSeq++)), live.entries, channels)
    tables.forEach { it.close(); Files.delete(it.path) }
    tables.clear()
    tables += out
}

// It merges EVERY table, so no older file is left that could still hold a deleted key.
// A compaction of only some files must keep the tombstone while an older file might hold the key
// (and Cassandra keeps it for gc_grace_seconds in case a replica missed the delete).
